const body = $input.first().json.body || {};
const payload = body.payload || {};
const student = payload.student || {};
const metadata = body.metadata || {};

const formattedTime = new Date(body.timestamp || Date.now()).toLocaleString('pt-BR', {
  timeZone: 'America/Sao_Paulo'
});

const reasonsList = Array.isArray(payload.reasons) 
  ? payload.reasons.join(', ') 
  : (payload.reasons || 'Não especificado');

const alertMessage = `🚨 *ALERTA DE OCORRÊNCIA CRÍTICA* 🚨\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `👤 *Aluno:* ${student.name || 'Desconhecido'} (Turma: ${student.class || 'N/A'})\n` +
  `🆔 *ID Ocorrência:* ${payload.occurrenceId || 'N/A'}\n` +
  `⚠️ *Gravidade:* ${(payload.severity || 'UNKNOWN').toUpperCase()}\n` +
  `🎯 *Destino:* ${payload.destination || 'Diretoria'}\n` +
  `📍 *Local:* ${payload.location || 'Não informado'}\n` +
  `👮 *Monitor Responsável:* ${payload.monitor || 'Sistema'}\n` +
  `⏰ *Horário:* ${formattedTime}\n` +
  `📝 *Motivo(s):* ${reasonsList}\n` +
  `💬 *Detalhes:* ${payload.details || 'Sem detalhes adicionais'}\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📲 *Origem:* ${metadata.source || 'prancheta-digital-pwa'} v${metadata.version || '1.0'}`;

return [{
  json: {
    alertMessage,
    occurrenceId: payload.occurrenceId,
    studentId: student.id,
    studentName: student.name,
    studentClass: student.class,
    severity: payload.severity,
    destination: payload.destination,
    location: payload.location,
    monitor: payload.monitor,
    reasons: payload.reasons,
    details: payload.details,
    timestamp: body.timestamp,
    rawPayload: payload
  }
}];
